const ashSoldierSheet=new Image();ashSoldierSheet.assetSrc='assets/ash-soldier-v1.png';
function ashSoldierFront(a,point,half=Math.PI/3){let angle=Math.atan2(point.y-a.origin.y,point.x-a.origin.x)-a.angle;return Math.abs(Math.atan2(Math.sin(angle),Math.cos(angle)))<=half+1e-8;}
function beginAshSoldier(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'ashShieldHammer',bespoke:true,windup:1.65,origin:{x:e.x,y:e.y},angle,fired:false};}
function ashSoldierGuard(e){let a=e.attack;return e.hp>0&&!(e.reactionStun>0)&&a?.pattern==='ashShieldHammer'&&e.elapsed<1&&dist(e,a.origin)<=24&&ashSoldierFront(a,p,Math.PI/2);}
const ashSoldierHitBase=hit;hit=(e,d)=>ashSoldierHitBase(e,d*(e.species==='r7e2'&&!e.dotTick&&ashSoldierGuard(e)?.35:1));
const ashSoldierAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e2')return ashSoldierAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='ashShieldHammer'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=190&&clear){beginAshSoldier(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,78*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,20)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=1.65){a.fired=true;e.struck=true;if(dist(p,a.origin)<=180+1e-8&&ashSoldierFront(a,p)&&lineClear(a.origin,p))hurt(86);playSound('impact',e.x,e.y);burst(e.x+Math.cos(a.angle)*100,e.y+Math.sin(a.angle)*100,60,'#ecb67a');}
 if(e.elapsed>=3.15){e.attack=null;e.state='idle';e.t=1.8;}
};
const ashSoldierDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e2'||!ashSoldierSheet.complete||!ashSoldierSheet.naturalWidth||!ashSoldierSheet.naturalHeight)return ashSoldierDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='ashShieldHammer')f={row:2,col:e.elapsed<1?0:e.elapsed<1.65?1:e.elapsed<1.95?2:3};let q=project(e.x,e.y),sw=ashSoldierSheet.naturalWidth/4,sh=ashSoldierSheet.naturalHeight/3,w=240,h=w*sh/sw,anchor=[.92,.92,.94][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,ashSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(ashSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const ashSoldierSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e2'?155:ashSoldierSizeBase(e);
const ashSoldierGroundBase=drawGroundEffects;drawGroundEffects=()=>{ashSoldierGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e2'):enemies)){let a=e.attack;if(e.species!=='r7e2'||e.hp<=0||a?.pattern!=='ashShieldHammer'||!visibleAt(e.x,e.y))continue;if(e.elapsed>=1.95){groundRing(e.x,e.y,35,'#9bddcf',2);continue;}let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=a.fired?'#ffd19a66':'#df864c22';ctx.strokeStyle='#efad72';ctx.lineWidth=a.fired?3:1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,180,a.angle-Math.PI/3,a.angle+Math.PI/3);ctx.closePath();ctx.fill();ctx.stroke();if(e.elapsed<1){ctx.strokeStyle='#f6d18e';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,45,a.angle-Math.PI/2,a.angle+Math.PI/2);ctx.stroke();}ctx.restore();}};
